use vstd::prelude::*;

verus! {
    /// Returns a vector of booleans indicating, for each index `i`,
    /// whether `a[i] < b[i]`.  Requires that the two input vectors
    /// have the same length.
    fn less(a: Vec<i8>, b: Vec<i8>) -> (res: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            // The result has the same length as the inputs
            res.len() == a.len(),
            // For every valid index i, res[i] == (a[i] < b[i])
            forall |i: usize| i < a.len() ==> res[i] == (a[i] < b[i]),
    {
        a.into_iter()
         .zip(b.into_iter())
         .map(|(x, y)| x < y)
         .collect()
    }
}

fn main() {
    // Example usage; not part of the verification
    let v1 = vec![1, 4, -2, 7];
    let v2 = vec![2, 3,  0, 7];
    let r = less(v1, v2);
    assert_eq!(r, vec![true, false, true, false]);
}